def hidden_rule_fn(state):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    if len(state) < 2:
        return state + [0]

    last = state[-1]
    second_last = state[-2]

    if is_prime(len(state)):
        # ploon-XOR: XOR of last two, mod 7
        new_val = (last ^ second_last) % 7
    else:
        # grolp-sum: sum of last two + 3, mod 7
        new_val = (last + second_last + 3) % 7

    return state + [new_val]
